const DB_NAME='hito-oboe-db',STORE='people';let db,people=[],screen='home',previous='home',activeTag='',pendingConversations=[],pendingDeletedConversation=null,pendingPhoto='',pendingTags=[],touchX=0,deferredInstall=null;
