function avatar(p){return p.photo?'<img src="'+p.photo+'" alt="">':esc(Array.from(p.name||'人')[0])}
function tagCounts(){let m=new Map;people.forEach(p=>tagsOf(p).forEach(t=>m.set(t,(m.get(t)||0)+1)));return m}
