function personCompletion(p){let basic=scoreFields(p,[[x=>x.name,35],[x=>x.reading,20],[x=>x.age,20],[x=>x.gender,25]]),work=scoreFields(p,[[x=>x.company,25],[x=>x.department,25],[x=>x.position,25],[x=>tagsOf(x).some(t=>tagTypesOf(x)[t]==='work'),25]]),priv=scoreFields(p,[[x=>tagsOf(x).some(t=>tagTypesOf(x)[t]==='private'),50],[x=>/(家族|子|娘|息子|妻|夫|ペット|出身|地元)/.test(x.traits||''),25],[x=>x.traits,25]]),hobby=scoreFields(p,[[x=>tagsOf(x).some(t=>tagTypesOf(x)[t]==='private'),80],[x=>x.hobbies,20]]),memo=scoreFields(p,[[x=>x.traits,35],[x=>x.nextQuestion,25],[x=>x.conversations?.length,40]]);return Math.round(basic*25+work*22+priv*18+hobby*18+memo*17)}
