function categoryStats(){let avg=items=>people.length?Math.round(people.reduce((s,p)=>s+scoreFields(p,items),0)/people.length*100):0;return[{name:'基本情報',done:avg([[x=>x.name,35],[x=>x.reading,20],[x=>x.age,20],[x=>x.gender,25]]),color:'#36b58b'},{name:'仕事',done:avg([[x=>x.company,25],[x=>x.department,25],[x=>x.position,25],[x=>tagsOf(x).some(t=>tagTypesOf(x)[t]==='work'),25]]),color:'#3d8ee8'},{name:'家族・プライベート',done:avg([[x=>tagsOf(x).some(t=>tagTypesOf(x)[t]==='private'),50],[x=>/(家族|子|娘|息子|妻|夫|ペット|出身|地元)/.test(x.traits||''),25],[x=>x.traits,25]]),color:'#f2b84b'},{name:'趣味・嗜好',done:avg([[x=>tagsOf(x).some(t=>tagTypesOf(x)[t]==='private'),80],[x=>x.hobbies,20]]),color:'#9b62d6'},{name:'人生イベント',done:avg([[x=>x.traits,35],[x=>x.nextQuestion,25],[x=>x.conversations?.length,40]]),color:'#e85d8f'}]}
function keywordTop(p){let tags=tagsOf(p),text=[p.hobbies,p.traits,p.conversations?.slice(-1)[0]?.text].filter(Boolean).join('、'),words=text.split(/[、。\n\s,]/).map(x=>x.trim()).filter(x=>x.length>1&&x.length<14);return[...tags,...words].filter((v,i,a)=>a.indexOf(v)===i).slice(0,3)}
