function card(p){let sub=[p.company,p.department].filter(Boolean).join(' ・ ')||p.position||'人物メモ',keys=keywordTop(p),tags=tagsOf(p).slice(0,5),score=personCompletion(p);return '<button class="person-card person-card-rich" data-id="'+p.id+'"><i class="avatar" '+avatarStyle(p)+'>'+avatar(p)+'</i><span class="person-info"><strong>'+esc(p.name)+'</strong><span>'+esc(sub)+'</span><em>'+esc(keys.join(' / ')||'キーワード未登録')+'</em><small>'+esc(recentEvent(p).slice(0,34))+'</small><span class="mini-tags">'+tags.map(t=>'<i>'+esc(t)+'</i>').join('')+'</span></span><b class="completion-badge">'+score+'%</b></button>'}
