function dailyDiscovery(){if(!people.length)return '<b>最初の1人を登録すると、ここに発見が出ます。</b><p>タグやメモが増えるほど、人物図鑑らしく育ちます。</p>';let counts=[...tagCounts().entries()].sort((a,b)=>b[1]-a[1]);if(counts[0]){let [t,n]=counts[0];return '<b>「'+esc(t)+'」が登録されている人が'+n+'人います</b><p>同じ話題でつながる人を眺めてみましょう。</p><button type="button" data-home-tag="'+esc(t)+'">このタグを見る</button>'}let p=[...people].sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0];return '<b>'+esc(p.name)+'さんの情報が最近更新されました</b><p>'+esc(recentEvent(p).slice(0,54))+'</p>'}
