function renderSearch(){renderColorManager();let allTags=[...new Set(people.flatMap(tagsOf))].sort((a,b)=>a.localeCompare(b,'ja'));$('tagFilters').innerHTML=allTags.map(t=>'<button class="chip '+(t===activeTag?'active':'')+'" data-tag="'+esc(t)+'">'+esc(t)+'</button>').join('');$('tagFilters').querySelectorAll('.chip').forEach(b=>b.onclick=()=>{activeTag=activeTag===b.dataset.tag?'':b.dataset.tag;renderSearch()});let q=normalize($('query').value),found=people.filter(p=>(!activeTag||tagsOf(p).includes(activeTag))&&(!q||[p.name,p.reading,p.company,p.department,p.position,p.favoriteFood,p.traits,p.birthday,...foodTagsOf(p),...tagsOf(p),...p.conversations.map(c=>c.text)].some(v=>normalize(v).includes(q)))),sort=$('sortSelect').value;if(sort==='name')found.sort((x,y)=>(x.reading||x.name).localeCompare(y.reading||y.name,'ja'));else if(sort==='department')found.sort(compareByCustomOrder);else found.sort((x,y)=>y.updatedAt-x.updatedAt);$('personCount').textContent=found.length+'人';$('personList').innerHTML=found.length?found.map(p=>listCard(p)).join(''):empty('見つかりませんでした','検索条件を変えてみてください。');bindCards($('personList'))}
