function checkDuplicateName(){let name=$('name').value.trim(),id=$('personId').value,dup=name&&people.find(p=>p.id!==id&&normalize(p.name)===normalize(name)),box=$('nameDuplicate');if(!box)return;box.classList.toggle('hidden',!dup);box.innerHTML=dup?'すでに「'+esc(dup.name)+'」が登録されています':''}
function readOrder(key){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return[]}}
function writeOrder(key,order){localStorage.setItem(key,JSON.stringify(order.filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i)))}
function storageKeys(){let keys=[];for(let i=0;i<localStorage.length;i++)keys.push(localStorage.key(i));return keys.filter(Boolean)}
function companyOrder(){let saved=readOrder('hitolog-company-order'),all=[...new Set(people.map(p=>p.company).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja'));return[...saved.filter(x=>all.includes(x)),...all.filter(x=>!saved.includes(x))]}
function departmentOrder(company=''){let key=company?'hitolog-department-order:'+company:'hitolog-department-order',saved=readOrder(key),all=[...new Set(people.filter(p=>!company||p.company===company).map(p=>p.department).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja')),legacy=!company?readOrder('hitolog-department-order'):[];if(!saved.length&&legacy.length)saved=legacy;return[...saved.filter(x=>all.includes(x)),...all.filter(x=>!saved.includes(x))]}
function personOrder(company='',department=''){let key='hitolog-person-order:'+company+'|'+department,saved=readOrder(key),all=people.filter(p=>(!company||p.company===company)&&(!department||p.department===department)).map(p=>p.id);return[...saved.filter(x=>all.includes(x)),...all.filter(x=>!saved.includes(x))]}
function rank(v,order){let i=order.indexOf(v||'');return i<0?9999:i}
function compareByCustomOrder(x,y){let co=companyOrder(),cx=rank(x.company,co),cy=rank(y.company,co);if(cx!==cy)return cx-cy;let company=x.company||y.company||'',doe=departmentOrder(company),dx=rank(x.department,doe),dy=rank(y.department,doe);if(dx!==dy)return dx-dy;let po=personOrder(company,x.department||y.department||''),px=rank(x.id,po),py=rank(y.id,po);if(px!==py)return px-py;return(x.reading||x.name).localeCompare(y.reading||y.name,'ja')}
function groupColor(kind,value){let key=kind==='company'?'companyColor':'departmentColor',fallback=kind==='company'?1:4,p=people.find(x=>x[kind]===value&&x[key]);return p?.[key]||colorFor(value,fallback)}
let orderView={level:'company',company:'',department:''};
function renderOrderManager(){let box=$('orderList');if(!box)return;let title=$('orderPanelTitle'),crumb=$('orderBreadcrumb'),hint=$('orderPanelHint');let order=[],key='',label=x=>x,clickAttr='';if(orderView.level==='company'){title.textContent='会社の並び順';hint.textContent='会社名を押すと、その会社内の部署の並び順を変更できます。';crumb.innerHTML='';order=companyOrder();key='hitolog-company-order';clickAttr='data-order-company'}else if(orderView.level==='department'){title.textContent='部署の並び順';hint.textContent='部署名を押すと、その部署内の人物の並び順を変更できます。';crumb.innerHTML='<button type="button" data-order-back="company">会社一覧</button><span>'+esc(orderView.company)+'</span>';order=departmentOrder(orderView.company);key='hitolog-department-order:'+orderView.company;clickAttr='data-order-department'}else{title.textContent='人物の並び順';hint.textContent='↑↓で人物の表示順を変更できます。';crumb.innerHTML='<button type="button" data-order-back="company">会社一覧</button><button type="button" data-order-back="department">'+esc(orderView.company)+'</button><span>'+esc(orderView.department)+'</span>';order=personOrder(orderView.company,orderView.department);key='hitolog-person-order:'+orderView.company+'|'+orderView.department;label=id=>people.find(p=>p.id===id)?.name||'不明な人物'}writeOrder(key,order);box.innerHTML=order.length?order.map((v,i)=>'<div class="order-row"><button class="order-name" type="button" '+clickAttr+'="'+esc(v)+'">'+esc(label(v))+'</button><button type="button" data-order-up="'+i+'" '+(i===0?'disabled':'')+'>↑</button><button type="button" data-order-down="'+i+'" '+(i===order.length-1?'disabled':'')+'>↓</button></div>').join(''):'<span class="choice-empty">まだ項目がありません</span>';box.querySelectorAll('[data-order-company]').forEach(b=>b.onclick=()=>{orderView={level:'department',company:b.dataset.orderCompany,department:''};renderOrderManager()});box.querySelectorAll('[data-order-department]').forEach(b=>b.onclick=()=>{orderView={level:'person',company:orderView.company,department:b.dataset.orderDepartment};renderOrderManager()});box.querySelectorAll('[data-order-up]').forEach(b=>b.onclick=()=>moveOrderItem(+b.dataset.orderUp,-1,key));box.querySelectorAll('[data-order-down]').forEach(b=>b.onclick=()=>moveOrderItem(+b.dataset.orderDown,1,key));crumb.querySelectorAll('[data-order-back]').forEach(b=>b.onclick=()=>{orderView=b.dataset.orderBack==='company'?{level:'company',company:'',department:''}:{level:'department',company:orderView.company,department:''};renderOrderManager()})}
function moveOrderItem(i,dir,key){let order=readOrder(key),j=i+dir;if(j<0||j>=order.length)return;[order[i],order[j]]=[order[j],order[i]];writeOrder(key,order);renderOrderManager();renderSearch()}
