async function applyGroupColor(kind,value,color,newName=''){if(!value)return;let name=(newName||value).trim(),y=typeof window.scrollY==='number'?window.scrollY:0,key=kind==='company'?'companyColor':'departmentColor';for(let p of people.filter(p=>p[kind]===value)){p={...p,updatedAt:Date.now(),[kind]:name,[key]:color};await request('readwrite',s=>s.put(p))}if(name!==value){if(kind==='company'){writeOrder('hitolog-company-order',companyOrder().map(x=>x===value?name:x));for(let k of storageKeys()){if(k.startsWith('hitolog-department-order:'+value)){let v=localStorage.getItem(k);localStorage.removeItem(k);localStorage.setItem('hitolog-department-order:'+name,v)}if(k.startsWith('hitolog-person-order:'+value+'|')){let v=localStorage.getItem(k);localStorage.removeItem(k);localStorage.setItem(k.replace('hitolog-person-order:'+value+'|','hitolog-person-order:'+name+'|'),v)}}}else{writeOrder('hitolog-department-order',departmentOrder().map(x=>x===value?name:x));for(let k of storageKeys()){if(k.startsWith('hitolog-department-order:'))writeOrder(k,readOrder(k).map(x=>x===value?name:x));if(k.includes('|'+value)){let v=localStorage.getItem(k);localStorage.removeItem(k);localStorage.setItem(k.replace('|'+value,'|'+name),v)}}}}await load();if(screen==='list')requestAnimationFrame(()=>scrollTo({top:y,behavior:'auto'}));toast((name!==value?'名前と':'')+'色を変更しました')}
