function normalizeCardLine(x){return String(x||'').normalize('NFKC').replace(/[|｜_=#]+/g,' ').replace(/\s+/g,' ').trim().replace(/([ぁ-んァ-ヶ一-龠々])\s+(?=[ぁ-んァ-ヶ一-龠々])/g,'$1')}
function isContactLine(x){return /(@|E-?mail|mail\.|https?|www|〒|^\w?\d{3}-\d{4}|\d{2,4}-\d{2,4}-\d{3,4}|TEL|FAX|携帯|電話|大阪府|東京都|北海道|(?:京都|大阪|兵庫|奈良|滋賀|和歌山|愛知|福岡|神奈川|埼玉|千葉|静岡|広島|宮城|沖縄)県|市|区|町|丁目|番地|オフィス|office|F$|階)/i.test(x)}
function isNoiseLine(x){return !x||x.length<2||/^[\d\s.,:;/-]+$/.test(x)||/(あしたを元気に|を元気に|ロゴ|TRIAE|クラボ|ヴァネックス|しるみて)/i.test(x)}
