function cleanCardValue(x){return String(x||'').replace(/[^\wぁ-んァ-ヶ一-龠々・ー\s]/g,' ').replace(/\s+/g,' ').trim()}
function safeDeptCandidate(x){let v=cleanCardValue(x);return v.length>=3&&v.length<=28&&!/[A-Za-z]{3,}|\d{3,}/.test(v)&&/(部|課|室|本部|事業部|チーム|グループ|営業|開発|企画|総務|人事|経理|広報|マーケ|エリア|運営)/.test(v)&&!/(株式会社|有限会社|合同会社|あした|元気|オフィス)/.test(v)?v:''}
function safeNameCandidate(x){let v=cleanCardValue(x).replace(/\s+/g,''),jp=(v.match(/[ぁ-んァ-ヶ一-龠々]/g)||[]).length;return v.length>=2&&v.length<=8&&jp>=2&&!/[A-Za-z0-9]|株式会社|有限会社|合同会社|部|課|室|本部|事業部|グループ|エリア|運営|営業|開発|企画|総務|人事|経理|広報|マーケ|代表|社長|取締役|部長|課長|係長|主任/.test(v)?v:''}
function parseCardLines(lines){let raw=cardTokens(lines),useful=raw.filter(x=>!isNoiseLine(x)),business=useful.filter(x=>!isContactLine(x)),companyLine=business.find(x=>/(株式会社|有限会社|合同会社|Inc\.|Ltd\.|Corporation|Company|Co\.,?\s*Ltd\.?)/i.test(x))||'',company=companyLine.replace(/\s+/g,'').replace(/株式會社/g,'株式会社'),position=business.find(x=>/(代表|社長|取締役|部長|課長|係長|主任|マネージャー|manager|director|president|ceo|cto|cfo)/i.test(x))||'',deptCandidates=business.filter(x=>x!==companyLine&&x!==position&&/(部|課|室|本部|事業部|チーム|グループ|営業|開発|企画|総務|人事|経理|広報|マーケ|エリア|運営|sales|design|product|engineering)/i.test(x)&&!/(株式会社|有限会社|合同会社)/.test(x)),department=deptCandidates.map(x=>bestExisting(x,'department')).find(Boolean)||'',nameCandidates=business.filter(x=>x!==companyLine&&x!==department&&x!==position).map(safeNameCandidate).filter(Boolean),name=nameCandidates.sort((a,b)=>b.length-a.length)[0]||'';return{name,company,department,position,raw,business}}
